package com.locallaunch.controller;
import com.locallaunch.dto.RatingRequest; import com.locallaunch.entity.CustomerRating; import com.locallaunch.service.RatingService; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/ratings") public class RatingController { private final RatingService service; public RatingController(RatingService s){service=s;} @PostMapping("/public/{productId}") public ResponseEntity<CustomerRating> add(@PathVariable Long productId,@Valid @RequestBody RatingRequest request){return ResponseEntity.ok(service.add(productId,request));} @GetMapping("/public/{productId}") public List<CustomerRating> get(@PathVariable Long productId){return service.get(productId);} }
